:root {
  --bg: #2b2b2b;
  --card: #f0e6d2;
  --ink: #2b2b2b;
  --accent: #8b5e3c;
  --green: #4a7c59;
  --red: #c0392b;
  --border: 4px solid var(--ink);
  --shadow: 6px 6px 0 var(--ink);
  --font: 16px/1.5 system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

[hidden] {
  display: none !important;
}

body {
  font: var(--font);
  background: var(--bg);
  color: var(--ink);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  background-image: linear-gradient(45deg, #333 25%, transparent 25%),
                    linear-gradient(-45deg, #333 25%, transparent 25%),
                    linear-gradient(45deg, transparent 75%, #333 75%),
                    linear-gradient(-45deg, transparent 75%, #333 75%);
  background-size: 20px 20px;
  background-position: 0 0, 0 10px, 10px -10px, -10px 0;
}

.library-card {
  background: var(--card);
  border: var(--border);
  box-shadow: var(--shadow);
  padding: 24px;
  width: 100%;
  max-width: 640px;
}

header {
  margin-bottom: 20px;
}

h1 {
  font-size: 1.75rem;
  letter-spacing: 1px;
  text-transform: uppercase;
}

.subtitle {
  color: var(--accent);
  font-size: 1rem;
}

.controls {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 20px;
  padding: 12px;
  border: 3px solid var(--ink);
  background: #e8dcc4;
}

.filter-label {
  display: flex;
  align-items: center;
  gap: 8px;
  cursor: pointer;
  font-weight: 600;
  font-size: 1rem;
}

.filter-label input[type="checkbox"] {
  width: 20px;
  height: 20px;
  accent-color: var(--accent);
  cursor: pointer;
}

.filter-label input[type="checkbox"]:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.count {
  font-weight: 700;
  font-size: 1rem;
  color: var(--accent);
  white-space: nowrap;
}

.book-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.book-item {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 16px;
  border: 3px solid var(--ink);
  background: #faf5ea;
  box-shadow: 3px 3px 0 var(--ink);
}

.book-info {
  flex: 1 1 180px;
  min-width: 0;
}

.book-title {
  font-weight: 700;
  font-size: 1.1rem;
  word-break: break-word;
}

.book-author {
  font-size: 0.95rem;
  color: #5a4a3a;
}

.status {
  display: inline-block;
  margin-top: 4px;
  padding: 2px 8px;
  font-size: 0.85rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  border: 2px solid var(--ink);
}

.status.available {
  background: var(--green);
  color: #fff;
}

.status.checked-out {
  background: var(--red);
  color: #fff;
}

.toggle-btn {
  font: inherit;
  font-weight: 700;
  font-size: 0.95rem;
  padding: 10px 16px;
  cursor: pointer;
  border: 3px solid var(--ink);
  background: var(--accent);
  color: #fff;
  box-shadow: 3px 3px 0 var(--ink);
  transition: background 0.1s, transform 0.05s, box-shadow 0.05s;
  white-space: nowrap;
}

.toggle-btn:hover {
  background: #a06e48;
}

.toggle-btn:active {
  transform: translate(3px, 3px);
  box-shadow: none;
}

.toggle-btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.toggle-btn.return {
  background: var(--green);
}

.toggle-btn.return:hover {
  background: #5a8f6a;
}

@media (max-width: 480px) {
  .library-card { padding: 16px; }
  h1 { font-size: 1.4rem; }
  .book-item { flex-direction: column; align-items: stretch; }
  .toggle-btn { width: 100%; }
  .controls { flex-direction: column; align-items: flex-start; }
}

const books = [
  { id: 1, title: 'The Pixel Frontier', author: 'Ada Lovelace', checkedOut: false },
  { id: 2, title: 'Sprites & Spells', author: 'Grace Hopper', checkedOut: false },
  { id: 3, title: 'Byte-Sized Tales', author: 'Alan Turing', checkedOut: false },
  { id: 4, title: 'Retro Render', author: 'Margaret Hamilton', checkedOut: false },
  { id: 5, title: 'The 8-Bit Odyssey', author: 'Linus Torvalds', checkedOut: false },
  { id: 6, title: 'Cache Me If You Can', author: 'Barbara Liskov', checkedOut: false },
];

const bookList = document.getElementById('bookList');
const filterCheckbox = document.getElementById('filterAvailable');
const countSpan = document.getElementById('checkedOutCount');

const statusLive = document.querySelector('.count');

function render() {
  const showAvailableOnly = filterCheckbox.checked;
  bookList.innerHTML = '';

  books.forEach(book => {
    const li = document.createElement('li');
    li.className = 'book-item';
    li.dataset.id = book.id;
    if (showAvailableOnly && book.checkedOut) {
      li.hidden = true;
    }

    const info = document.createElement('div');
    info.className = 'book-info';

    const title = document.createElement('div');
    title.className = 'book-title';
    title.textContent = book.title;

    const author = document.createElement('div');
    author.className = 'book-author';
    author.textContent = book.author;

    const status = document.createElement('span');
    status.className = 'status ' + (book.checkedOut ? 'checked-out' : 'available');
    status.textContent = book.checkedOut ? 'Checked out' : 'Available';

    info.append(title, author, status);

    const btn = document.createElement('button');
    btn.className = 'toggle-btn' + (book.checkedOut ? ' return' : '');
    btn.type = 'button';
    btn.dataset.id = book.id;
    btn.textContent = book.checkedOut ? 'Return' : 'Check out';
    btn.setAttribute('aria-label',
      (book.checkedOut ? 'Return ' : 'Check out ') + book.title);

    li.append(info, btn);
    bookList.appendChild(li);
  });

  updateCount();
}

function updateCount() {
  const checkedOutCount = books.filter(b => b.checkedOut).length;
  countSpan.textContent = checkedOutCount;
  statusLive.setAttribute('aria-label',
    checkedOutCount + ' of ' + books.length + ' books checked out');
}

bookList.addEventListener('click', (e) => {
  const btn = e.target.closest('.toggle-btn');
  if (!btn) return;
  const id = Number(btn.dataset.id);
  const book = books.find(b => b.id === id);
  if (!book) return;
  book.checkedOut = !book.checkedOut;
  render();
  const newBtn = bookList.querySelector(`.toggle-btn[data-id="${id}"]`);
  if (newBtn && !newBtn.closest('li').hidden) newBtn.focus();
});

filterCheckbox.addEventListener('change', render);

render();
